{
  "capability": "carrier-relationship-management",
  "version": "1.0.0",
  "scenarios": [
    {
      "id": "CRM-001",
      "name": "Basic carrier scorecard evaluation and allocation recommendation",
      "difficulty": "easy",
      "category": "scorecarding",
      "context": {
        "situation": "You manage the carrier portfolio for a mid-size consumer goods manufacturer shipping 200 FTL loads per week. Your quarterly scorecard review is due. Three carriers service your Chicago to Dallas lane (8 loads/week): Heartland Carriers (primary, 60% allocation), Crosswind Logistics (secondary, 30%), and DAT spot procurement (tertiary, 10%). Here are the Q3 scorecard numbers for each carrier on this lane.",
        "available_data": {
          "lane": "Chicago, IL to Dallas, TX",
          "lane_volume": "8 loads/week",
          "lane_annual_spend": "$1.15M",
          "heartland_carriers": {
            "allocation": "60%",
            "rate_per_mile": "$2.38",
            "otd": "97.2%",
            "tender_acceptance": "94%",
            "claims_ratio": "0.2%",
            "invoice_accuracy": "98.5%"
          },
          "crosswind_logistics": {
            "allocation": "30%",
            "rate_per_mile": "$2.22",
            "otd": "88.1%",
            "tender_acceptance": "76%",
            "claims_ratio": "1.4%",
            "invoice_accuracy": "91.2%"
          },
          "spot_procurement": {
            "allocation": "10%",
            "average_rate_per_mile": "$2.65",
            "dat_contract_benchmark": "$2.28/mile"
          }
        }
      },
      "task": "Evaluate the three carriers' performance, recommend allocation changes for next quarter, and identify any carriers requiring corrective action.",
      "evaluation_criteria": [
        {
          "criterion": "scorecard_analysis",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies Heartland as a top-tier carrier (all metrics exceed targets) and Crosswind as an underperformer (OTD below 90%, tender acceptance below 80%, claims ratio above 1%, invoice accuracy below 93%). References specific thresholds from carrier management standards.",
            "fail": "Treats both carriers as similar performers, or focuses only on rate without evaluating service metrics. Does not reference specific KPI thresholds."
          }
        },
        {
          "criterion": "allocation_recommendation",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends increasing Heartland's allocation (to 70-80%) based on superior performance, and either issuing a corrective action plan for Crosswind or reducing their allocation (to 15-20%). Notes that 10% spot at $2.65/mile when DAT benchmark is $2.28 suggests the routing guide needs attention. The recommendation reflects the principle that top performers earn more volume.",
            "fail": "Recommends maintaining the status quo or reducing Heartland's allocation. Suggests awarding more volume to Crosswind based on lower rate alone. Does not address the spot premium issue."
          }
        },
        {
          "criterion": "corrective_action",
          "weight": 0.35,
          "rubric": {
            "pass": "Identifies Crosswind as needing a formal corrective action plan with specific metrics (OTD target ≥92% at 30 days, ≥95% at 60 days; tender acceptance ≥85%; invoice accuracy ≥95%), a defined timeline (30/60/90 day checkpoints), and a stated consequence (further volume reduction or exit if targets not met). Recommends a direct conversation with Crosswind's account manager.",
            "fail": "Does not identify the need for corrective action. Suggests vague 'monitoring' without specific metrics or timeline. Recommends immediate termination without giving the carrier an opportunity to improve."
          }
        }
      ]
    },
    {
      "id": "CRM-002",
      "name": "FMCSA compliance vetting for new carrier onboarding",
      "difficulty": "easy",
      "category": "compliance-vetting",
      "context": {
        "situation": "Your operations team wants to onboard a new carrier, Falcon Ridge Transport (MC-881234), for a regional lane from Nashville to Charlotte (3 loads/week, dry van). Falcon Ridge quoted $1.85/mile — about 12% below your current carrier's rate. Before approving, you need to vet them. You've pulled their FMCSA data.",
        "available_data": {
          "carrier_name": "Falcon Ridge Transport",
          "mc_number": "MC-881234",
          "authority_status": "Active",
          "authority_grant_date": "2025-08-15",
          "months_operating": 6,
          "fleet_size": "8 trucks",
          "insurance_auto_liability": "$750,000",
          "insurance_cargo": "$50,000",
          "safety_rating": "Unrated",
          "csa_unsafe_driving_percentile": 42,
          "csa_hos_percentile": 68,
          "csa_vehicle_maintenance_percentile": 81,
          "current_carrier_rate": "$2.10/mile",
          "dat_lane_benchmark": "$1.98/mile"
        }
      },
      "task": "Evaluate Falcon Ridge Transport's compliance profile and provide an onboarding recommendation with any conditions or concerns.",
      "evaluation_criteria": [
        {
          "criterion": "compliance_assessment",
          "weight": 0.40,
          "rubric": {
            "pass": "Identifies multiple concerns: (1) authority is only 6 months old — new entrant risk, (2) auto liability at $750K meets FMCSA minimum but is below the recommended $1M standard for a quality carrier portfolio, (3) cargo insurance at $50K is below the typical $100K minimum, (4) Vehicle Maintenance CSA at 81st percentile is a red flag (above the 75th percentile threshold), and (5) unrated safety rating is normal for a new carrier but means reliance on CSA scores is critical.",
            "fail": "Approves the carrier based solely on active authority status. Does not identify the insurance shortfall or the elevated Vehicle Maintenance CSA score. Treats FMCSA minimum insurance as sufficient."
          }
        },
        {
          "criterion": "onboarding_recommendation",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends conditional onboarding: (1) require insurance increase to $1M auto and $100K cargo before first load, (2) monitor the Vehicle Maintenance CSA closely with quarterly checks, (3) run a 30-day trial with minimum 5 loads before full allocation, (4) flag the 6-month authority age as a risk factor — new carriers have higher failure rates. Notes that the $1.85/mile rate is 6% below DAT benchmark, which could indicate the carrier is under-pricing to win business — a sustainability concern.",
            "fail": "Recommends full onboarding without conditions. Does not require insurance increases. Does not flag the below-benchmark rate as a potential sustainability risk."
          }
        },
        {
          "criterion": "rate_analysis",
          "weight": 0.25,
          "rubric": {
            "pass": "Notes that Falcon Ridge's $1.85/mile is 12% below the current carrier and 6% below DAT benchmark. Questions whether this rate is sustainable for an 8-truck fleet — a carrier pricing below market to win business may cut corners on maintenance or driver pay, or may renegotiate rates after they've been awarded the lane.",
            "fail": "Accepts the low rate uncritically as a cost savings opportunity. Does not benchmark against DAT. Does not consider the sustainability of below-market pricing for a small carrier."
          }
        }
      ]
    },
    {
      "id": "CRM-003",
      "name": "Basic rate benchmarking and renegotiation trigger identification",
      "difficulty": "easy",
      "category": "rate-negotiation",
      "context": {
        "situation": "During your quarterly rate benchmarking analysis, you compare your top 10 contract lanes against DAT's 90-day contract averages. Most lanes are within ±8% of DAT, but three lanes stand out as outliers.",
        "available_data": {
          "outlier_lanes": [
            {
              "lane": "Atlanta, GA to Chicago, IL",
              "carrier": "Summit Express",
              "contract_rate": "$2.85/mile",
              "dat_benchmark": "$2.32/mile",
              "premium_percentage": "22.8%",
              "volume": "6 loads/week",
              "carrier_otd": "93%",
              "tender_acceptance": "89%"
            },
            {
              "lane": "Los Angeles, CA to Phoenix, AZ",
              "carrier": "Desert Sun Freight",
              "contract_rate": "$1.75/mile",
              "dat_benchmark": "$2.15/mile",
              "discount_percentage": "-18.6%",
              "volume": "4 loads/week",
              "carrier_otd": "96%",
              "tender_acceptance": "92%"
            },
            {
              "lane": "Dallas, TX to Memphis, TN",
              "carrier": "Riverbend Carriers",
              "contract_rate": "$2.48/mile",
              "dat_benchmark": "$2.05/mile",
              "premium_percentage": "21.0%",
              "volume": "3 loads/week",
              "carrier_otd": "87%",
              "tender_acceptance": "72%"
            }
          ],
          "dat_benchmark_tolerance": "±8%"
        }
      },
      "task": "Analyze each outlier lane, determine whether renegotiation is warranted, and recommend a specific action for each.",
      "evaluation_criteria": [
        {
          "criterion": "lane_analysis",
          "weight": 0.40,
          "rubric": {
            "pass": "Correctly identifies: (1) Atlanta-Chicago with Summit Express is 22.8% above DAT with only adequate service — clear renegotiation trigger. (2) LA-Phoenix with Desert Sun is 18.6% BELOW DAT — this means the carrier may be underpriced and at exit risk despite excellent performance. (3) Dallas-Memphis with Riverbend is 21% above DAT with poor OTD (87%) and low tender acceptance (72%) — this is both overpriced and underperforming.",
            "fail": "Treats all three lanes the same (e.g., 'renegotiate all three'). Does not recognize the LA-Phoenix situation as a below-market risk. Focuses only on the two above-DAT lanes."
          }
        },
        {
          "criterion": "action_recommendations",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends: (1) Summit Express ATL-CHI: initiate rate renegotiation targeting $2.45-$2.55/mile, using DAT data as the basis for discussion. If Summit won't move within 10% of DAT, include in next mini-bid. (2) Desert Sun LA-PHX: do NOT renegotiate downward — proactively discuss with the carrier whether this rate is sustainable. Consider a modest rate increase (to $1.90-$1.95/mile) to protect against carrier exit. (3) Riverbend DAL-MEM: issue corrective action on service AND renegotiate rate simultaneously. If neither improves in 60 days, replace via mini-bid.",
            "fail": "Recommends renegotiating all three lanes for lower rates. Does not recognize the Desert Sun underpricing risk. Addresses rate without addressing Riverbend's service failures."
          }
        },
        {
          "criterion": "market_awareness",
          "weight": 0.25,
          "rubric": {
            "pass": "Demonstrates understanding that a carrier pricing 18.6% below DAT is a risk signal — unsustainable pricing leads to service degradation, tender rejections, or carrier exit. References the concept of carrier floor pricing and the long-term cost of losing a high-performing carrier on a lane.",
            "fail": "Views the below-DAT rate purely as a cost advantage. Does not consider sustainability or carrier economics."
          }
        }
      ]
    },
    {
      "id": "CRM-004",
      "name": "Drafting a carrier performance review communication",
      "difficulty": "easy",
      "category": "relationship-management",
      "context": {
        "situation": "Mountain West Trucking has been your primary carrier on 5 lanes in the Western region for 18 months. They've had an outstanding quarter: 97.5% OTD (vs. portfolio average of 93.2%), 96% tender acceptance, 0.1% claims ratio, and 99.2% invoice accuracy. You want to recognize their performance and propose allocation increases. Your Q4 allocation review is coming up.",
        "available_data": {
          "carrier_name": "Mountain West Trucking",
          "relationship_duration_months": 18,
          "lanes_served": 5,
          "weekly_loads": 22,
          "annual_spend": "$3.8M",
          "q3_otd": "97.5%",
          "q3_tender_acceptance": "96%",
          "q3_claims_ratio": "0.1%",
          "q3_invoice_accuracy": "99.2%",
          "portfolio_avg_otd": "93.2%",
          "portfolio_avg_tender": "87.4%",
          "proposed_allocation_increase": "from 55% to 70% on their top 3 lanes",
          "new_lane_opportunity": "Seattle to Denver, 4 loads/week"
        }
      },
      "task": "Draft a positive performance review communication to Mountain West Trucking's VP of Sales that recognizes their Q3 performance and proposes specific allocation increases and a new lane opportunity.",
      "evaluation_criteria": [
        {
          "criterion": "specificity_and_data",
          "weight": 0.35,
          "rubric": {
            "pass": "Cites specific metrics (97.5% OTD, 96% tender acceptance, etc.) and compares to portfolio averages. Mentions specific allocation increases (55% to 70%) and the new Seattle-Denver lane opportunity. Avoids vague praise like 'great job' in favor of quantified recognition.",
            "fail": "Generic praise without citing specific numbers. Does not reference comparative performance against portfolio averages. Vague about what the carrier is earning as a result of their performance."
          }
        },
        {
          "criterion": "tone_and_relationship",
          "weight": 0.30,
          "rubric": {
            "pass": "Tone is warm, specific, and partnership-oriented. Frames the allocation increase and new lane as a reward earned by performance, not a favor. Mentions the carrier by name, references their team's contributions, and positions this as a deepening partnership. Avoids procurement-speak or generic vendor language.",
            "fail": "Cold or transactional tone. Treats the allocation increase as a business-as-usual decision rather than recognition of exceptional performance. Uses generic vendor management language."
          }
        },
        {
          "criterion": "actionable_next_steps",
          "weight": 0.35,
          "rubric": {
            "pass": "Proposes specific next steps: allocation increase effective date, rate discussion for the new Seattle-Denver lane, and a meeting to discuss future growth opportunities. Includes a concrete ask (e.g., 'Can we schedule a call next week to discuss the Seattle-Denver opportunity and your capacity?').",
            "fail": "No specific next steps. Leaves the communication as a congratulatory note without progressing the relationship. Does not propose a meeting or timeline for the allocation changes."
          }
        }
      ]
    },
    {
      "id": "CRM-005",
      "name": "Spot vs. contract decision on an irregular lane",
      "difficulty": "easy",
      "category": "contract-management",
      "context": {
        "situation": "Your sales team just won a new customer that requires 1-2 loads per week from your Memphis plant to a distribution center in Portland, OR. The lane is approximately 2,100 miles. Your current routing guide has no carriers for this lane. You need to decide how to handle freight procurement for this lane. The market is currently in a transitional phase — OTRI is at 8%, spot rates are roughly equal to contract benchmarks.",
        "available_data": {
          "lane": "Memphis, TN to Portland, OR",
          "distance_miles": 2100,
          "volume": "1-2 loads/week (irregular, customer orders vary)",
          "equipment": "53-foot dry van",
          "dat_contract_benchmark": "$3.15/mile",
          "dat_spot_average": "$3.08/mile",
          "spot_contract_spread": "-2.2%",
          "market_otri": "8%",
          "customer_delivery_window": "5 business days (flexible)",
          "customer_annual_revenue": "$420K (new customer, first year)"
        }
      },
      "task": "Recommend a freight procurement strategy for this new lane, including whether to contract or go spot, carrier sourcing approach, and risk considerations.",
      "evaluation_criteria": [
        {
          "criterion": "strategy_recommendation",
          "weight": 0.40,
          "rubric": {
            "pass": "Recommends starting with spot market for 60-90 days to establish actual volume patterns before committing to a contract. Notes that 1-2 loads/week of irregular volume is difficult to contract at competitive rates because carriers can't dedicate capacity to inconsistent freight. With spot-contract spread at only -2.2%, spot is essentially at parity with contract. Suggests evaluating after 90 days: if volume stabilizes at 2+/week, consider contracting; if it stays at 1/week, maintain spot with preferred carrier relationships.",
            "fail": "Recommends immediately contracting this lane without understanding volume patterns. Suggests running a full RFP for 1-2 loads/week. Does not consider the volume irregularity as a factor in carrier willingness to contract."
          }
        },
        {
          "criterion": "carrier_sourcing",
          "weight": 0.30,
          "rubric": {
            "pass": "Suggests identifying 2-3 preferred broker partners with strong coverage on long-haul West Coast lanes for spot procurement. Recommends vetting any spot carrier (FMCSA check, insurance verification) even for single loads. Notes that for a 2,100-mile lane, the carrier should have driver domicile within 100 miles of Memphis or be willing to relay.",
            "fail": "Suggests posting to open load boards without carrier vetting. Does not mention FMCSA compliance for spot carriers. Ignores the operational challenge of a 2,100-mile lane."
          }
        },
        {
          "criterion": "risk_assessment",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies this as a new customer in the first year ($420K revenue) where service failures carry disproportionate relationship risk. Recommends tracking spot carrier performance from day one to build data for future contract decisions. Notes the 5-day flexible delivery window provides buffer but should not be used as an excuse for poor carrier selection.",
            "fail": "Does not consider the new customer relationship risk. Does not plan for future transition from spot to contract. Treats this as a purely operational/cost decision."
          }
        }
      ]
    },
    {
      "id": "CRM-006",
      "name": "Fuel surcharge table comparison and total cost analysis",
      "difficulty": "easy",
      "category": "rate-negotiation",
      "context": {
        "situation": "Two carriers have submitted rate proposals for your Atlanta to Miami lane (5 loads/week, approximately 660 miles). Both are qualified carriers with similar service histories. You need to determine which is actually cheaper when total cost is modeled across diesel price scenarios. Current DOE diesel average is $3.92/gallon.",
        "available_data": {
          "lane": "Atlanta, GA to Miami, FL",
          "distance_miles": 660,
          "volume": "5 loads/week",
          "carrier_a": {
            "name": "Southern Express",
            "linehaul_per_mile": "$2.42",
            "fsc_base_diesel": "$3.50/gal",
            "fsc_increment": "$0.01/mile per $0.05 diesel increase",
            "detention_rate": "$75/hr after 2 hrs free",
            "avg_detention_hrs_per_load": 0.5
          },
          "carrier_b": {
            "name": "Gulf Coast Freight",
            "linehaul_per_mile": "$2.28",
            "fsc_base_diesel": "$2.90/gal",
            "fsc_increment": "$0.018/mile per $0.05 diesel increase",
            "detention_rate": "$85/hr after 1.5 hrs free",
            "avg_detention_hrs_per_load": 0.8
          },
          "current_doe_diesel": "$3.92/gal"
        }
      },
      "task": "Model total cost per load for both carriers at three diesel price points ($3.25, $3.92, $4.50) and recommend which carrier to award as primary. Show your work.",
      "evaluation_criteria": [
        {
          "criterion": "cost_modeling",
          "weight": 0.50,
          "rubric": {
            "pass": "Calculates total cost per load (linehaul + FSC + expected detention) for both carriers at all three diesel prices. Shows that Gulf Coast's lower linehaul is offset by their aggressive FSC schedule and higher detention cost. At current diesel ($3.92), Southern Express total cost should be approximately $1,660-$1,700 per load while Gulf Coast is approximately $1,680-$1,720. At $4.50 diesel, the gap widens significantly in Southern Express's favor.",
            "fail": "Compares only linehaul rates without modeling FSC. Does not calculate at multiple diesel scenarios. Awards based on the $0.14/mile linehaul difference without checking total cost."
          }
        },
        {
          "criterion": "fsc_analysis",
          "weight": 0.25,
          "rubric": {
            "pass": "Identifies that Gulf Coast's FSC base of $2.90/gal (vs. Southern Express at $3.50) means Gulf Coast starts charging FSC $0.60/gal sooner. Combined with the steeper increment ($0.018 vs. $0.01), Gulf Coast's FSC structure is significantly more expensive at elevated diesel prices. Notes this as a common carrier tactic — low linehaul with aggressive FSC.",
            "fail": "Does not analyze the FSC tables beyond noting they exist. Does not identify the base price difference as the key driver of total cost divergence."
          }
        },
        {
          "criterion": "recommendation",
          "weight": 0.25,
          "rubric": {
            "pass": "Recommends Southern Express as primary based on total cost advantage at current and high diesel prices, despite the higher linehaul rate. Notes that the more transparent FSC structure provides better cost predictability. May suggest Gulf Coast as secondary with a recommendation to renegotiate their FSC table.",
            "fail": "Recommends Gulf Coast based on the lower linehaul rate alone. Does not factor total cost or FSC structure into the recommendation."
          }
        }
      ]
    },
    {
      "id": "CRM-007",
      "name": "Routing guide failure analysis and remediation",
      "difficulty": "easy",
      "category": "portfolio-strategy",
      "context": {
        "situation": "Your operations manager reports that spot freight as a percentage of total freight has increased from 12% to 31% over the last 60 days. The spot premium over contract rates is averaging 22%. This is costing approximately $85,000/month in incremental freight spend. You need to diagnose the cause and fix the routing guide.",
        "available_data": {
          "total_weekly_loads": 180,
          "spot_percentage_60_days_ago": "12%",
          "spot_percentage_current": "31%",
          "spot_premium_over_contract": "22%",
          "monthly_incremental_cost": "$85,000",
          "top_5_spot_lanes": [
            {"lane": "Chicago to Atlanta", "spot_loads_per_week": 6, "primary_carrier_tender_acceptance": "62%"},
            {"lane": "Dallas to LA", "spot_loads_per_week": 5, "primary_carrier_tender_acceptance": "58%"},
            {"lane": "Memphis to Charlotte", "spot_loads_per_week": 4, "primary_carrier_tender_acceptance": "71%"},
            {"lane": "Houston to Denver", "spot_loads_per_week": 3, "primary_carrier_tender_acceptance": "55%"},
            {"lane": "Atlanta to Nashville", "spot_loads_per_week": 3, "primary_carrier_tender_acceptance": "68%"}
          ],
          "market_otri": "11%",
          "dat_spot_vs_contract_spread": "+14%"
        }
      },
      "task": "Diagnose the root cause of the routing guide failure, propose a remediation plan, and recommend preventive measures.",
      "evaluation_criteria": [
        {
          "criterion": "root_cause_diagnosis",
          "weight": 0.40,
          "rubric": {
            "pass": "Identifies that tender acceptance rates on the top 5 spot lanes (55-71%) are well below the 90% target, indicating contract rates on these lanes are below what carriers are willing to haul for. Notes the OTRI at 11% signals a tightening market where carriers are becoming selective — contract rates set in a softer market are now below the carriers' floor. This is a market cycle issue, not a carrier performance issue.",
            "fail": "Blames carriers for poor performance without recognizing the market has shifted. Suggests penalizing carriers for tender rejections without addressing the rate misalignment. Does not connect the OTRI indicator to the routing guide failure."
          }
        },
        {
          "criterion": "remediation_plan",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends a targeted mini-bid or rate renegotiation on the 5 worst lanes (not a full RFP — that takes 12 weeks). For immediate relief: negotiate rate adjustments on the top 5 lanes to within 5% of current DAT benchmarks. Carriers will re-accept tenders if rates reflect market reality. Also recommends adding backup carriers to the routing guide (most of these lanes likely have weak secondary/tertiary coverage).",
            "fail": "Recommends a full RFP (too slow for an $85K/month problem). Suggests finding cheaper carriers rather than adjusting rates. Does not prioritize the highest-impact lanes."
          }
        },
        {
          "criterion": "prevention",
          "weight": 0.25,
          "rubric": {
            "pass": "Recommends: (1) weekly monitoring of tender acceptance by lane with a 80% threshold trigger for rate review, (2) market-based reopener clauses in future contracts allowing rate adjustment when DAT moves >15%, (3) quarterly rate benchmarking against DAT/Greenscreens, not just annual RFP.",
            "fail": "Does not suggest ongoing monitoring or structural contract changes. Treats this as a one-time fix rather than a systemic vulnerability."
          }
        }
      ]
    },
    {
      "id": "CRM-008",
      "name": "Rate negotiation strategy for contract renewal in a tightening market",
      "difficulty": "medium",
      "category": "rate-negotiation",
      "context": {
        "situation": "Your 12-month carrier contract with Pinnacle Transport expires in 45 days. Pinnacle is your largest carrier (35% of total freight spend, $8.2M annually, 28 lanes). They've been a strong performer: 94% OTD, 91% tender acceptance. The market has shifted since you signed the contract — OTRI has risen from 5% to 13%, DAT spot rates are 18% above your contract rates on average, and capacity is tightening. Pinnacle's account manager has requested a meeting to 'discuss renewal terms' — you know a rate increase request is coming.",
        "available_data": {
          "carrier": "Pinnacle Transport",
          "current_annual_spend": "$8.2M",
          "portfolio_share": "35%",
          "lanes_served": 28,
          "weekly_loads": 65,
          "current_otd": "94%",
          "current_tender_acceptance": "91%",
          "contract_expiry": "45 days",
          "market_otri": "13%",
          "avg_spot_premium_over_contract": "18%",
          "dat_benchmark_avg_increase_since_contract": "12%",
          "pinnacle_reported_cost_increase": "driver pay +8%, insurance +15%, fuel +6%",
          "your_budget_target": "hold freight cost increase to <5%",
          "competing_carrier_rates": "2-3 carriers can cover 60% of Pinnacle's lanes at rates 5-8% above current Pinnacle rates"
        }
      },
      "task": "Develop a negotiation strategy for the Pinnacle contract renewal, including your opening position, concession plan, walk-away point, and alternatives if negotiation fails.",
      "evaluation_criteria": [
        {
          "criterion": "market_context_awareness",
          "weight": 0.25,
          "rubric": {
            "pass": "Acknowledges this is a carrier-favorable market (OTRI 13%, spot 18% above contract). Recognizes that Pinnacle has been honoring below-market rates for months — they have legitimate grounds for an increase. Notes that demanding no increase or a reduction would be unrealistic and relationship-damaging given market conditions.",
            "fail": "Approaches this as a standard cost-reduction negotiation. Does not acknowledge market conditions. Suggests hardball tactics (e.g., threatening to move freight) that would backfire in a tight market."
          }
        },
        {
          "criterion": "negotiation_strategy",
          "weight": 0.35,
          "rubric": {
            "pass": "Proposes: (1) Opening position of 5-6% increase (below Pinnacle's likely ask of 10-15% but above your budget target of 5%). (2) Concession plan offering non-rate value — faster payment terms (Net 15), volume commitment guarantee, drop-trailer program, multi-year contract (24 months with a pre-agreed year-2 escalator). (3) Lane-by-lane negotiation rather than a blanket increase — some lanes may need 8-10%, others may need only 3-4%. (4) Walk-away point of 8-9% blended increase.",
            "fail": "Has no structured negotiation plan. Suggests accepting whatever Pinnacle asks for. Does not use non-rate concessions. Proposes a blanket rate change rather than lane-level negotiation."
          }
        },
        {
          "criterion": "contingency_planning",
          "weight": 0.20,
          "rubric": {
            "pass": "Identifies that 35% portfolio concentration with one carrier is a vulnerability. Plans to qualify 2-3 alternative carriers on Pinnacle's top 10 lanes as a negotiation backstop. Notes that fully replacing 65 loads/week in a tight market would take 60-90 days. Recommends beginning alternative carrier qualification immediately, not waiting for negotiation to fail.",
            "fail": "Assumes negotiation will succeed without contingency. Does not begin qualifying alternatives. Overlooks the 35% concentration risk."
          }
